-- chat_voice_messages (Phase 12.5 plan 04, VOICE-01..06; D-846, D-847, D-859, D-861, D-865; T-12.5-10..14).
-- Generated by `pnpm db:generate --name=chat_voice_messages`, then reshaped by hand. EXPAND-ONLY: nothing is removed,
-- re-typed or made mandatory. A chat message is plain text OR one recording (D-846): `body` becomes nullable, the row
-- gains `media_asset_id` (a foreign key to `media_assets`, NO ACTION) and `voice_seconds`, two CHECKs state the
-- exactly-one rule, a partial unique index makes a take usable once, and the INSERT policy accepts a recording only
-- when the asset is the author's own ready `audio`/`voice` asset of the tenant with the same duration. D-865: the
-- column, the CHECKs and the index ship to every tenant database.
--
-- Every existing row has a body and no asset, so it satisfies both CHECKs; both are added NOT VALID and then
-- validated (a SHARE UPDATE EXCLUSIVE lock, writers are not blocked). The body CHECK keeps its NAME (the service maps
-- it to `body_required`), and its swap is ONE `alter table` statement (drop + add NOT VALID), as is the policy
-- replacement (one policy statement, `with check`), because the local CLI does not wrap a file in a transaction and a gap
-- between a drop and an add would let a bad row or a bad insert through. No UPDATE or DELETE policy or grant is added
-- (D-859): the grants of `chat_messages` are table-level, so the new columns need none. Applied locally with
-- `pnpm supabase migration up` (never a reset); hosted projects only through the release.
ALTER TABLE "chat_messages" ALTER COLUMN "body" DROP NOT NULL;--> statement-breakpoint
ALTER TABLE "chat_messages" ADD COLUMN "media_asset_id" uuid;--> statement-breakpoint
ALTER TABLE "chat_messages" ADD COLUMN "voice_seconds" smallint;--> statement-breakpoint
ALTER TABLE "chat_messages" ADD CONSTRAINT "chat_messages_media_asset_id_media_assets_id_fk" FOREIGN KEY ("media_asset_id") REFERENCES "public"."media_assets"("id") ON DELETE no action ON UPDATE no action NOT VALID;--> statement-breakpoint
CREATE UNIQUE INDEX "chat_messages_tenant_media_asset_uq" ON "chat_messages" USING btree ("tenant_id","media_asset_id") WHERE "chat_messages"."media_asset_id" is not null;--> statement-breakpoint
ALTER TABLE "chat_messages" DROP CONSTRAINT "chat_messages_body_chk", ADD CONSTRAINT "chat_messages_body_chk" CHECK ("chat_messages"."body" is null or char_length(btrim("chat_messages"."body", E' \t\n\r')) between 1 and 2000) NOT VALID;--> statement-breakpoint
ALTER TABLE "chat_messages" ADD CONSTRAINT "chat_messages_content_chk" CHECK (("chat_messages"."body" is not null and "chat_messages"."media_asset_id" is null and "chat_messages"."voice_seconds" is null) or ("chat_messages"."body" is null and "chat_messages"."media_asset_id" is not null and "chat_messages"."voice_seconds" between 1 and 300)) NOT VALID;--> statement-breakpoint
ALTER TABLE "chat_messages" VALIDATE CONSTRAINT "chat_messages_media_asset_id_media_assets_id_fk";--> statement-breakpoint
ALTER TABLE "chat_messages" VALIDATE CONSTRAINT "chat_messages_body_chk";--> statement-breakpoint
ALTER TABLE "chat_messages" VALIDATE CONSTRAINT "chat_messages_content_chk";--> statement-breakpoint
alter policy "chat_messages_insert" on "chat_messages" to authenticated with check (tenant_id = app.tenant_id() and author_user_id = app.user_id() and ((author_side = 'staff' and app.tenant_role() in ('admin_tenant', 'support_tenant') and exists (select 1 from public.chat_conversations c where c.id = chat_messages.conversation_id and c.kind = 'support')) or (author_side = 'member' and exists (select 1 from public.chat_participants p where p.conversation_id = chat_messages.conversation_id and p.tenant_id = app.tenant_id() and p.user_id = app.user_id()))) and (media_asset_id is null or exists (select 1 from public.media_assets a where a.id = chat_messages.media_asset_id and a.tenant_id = app.tenant_id() and a.owner_user_id = app.user_id() and a.kind = 'audio' and a.purpose = 'voice' and a.status = 'ready' and a.deleted_at is null and a.duration_seconds = chat_messages.voice_seconds)));
